#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Virginia — one-time setup: GitHub repo, Railway hosting, Anthropic key, Claude connector.
# Run from the project folder in Git Bash:   bash docs/SETUP-WIZARD.sh
# Re-running is safe: values already in .env are offered as defaults.

cd "$(dirname "${BASH_SOURCE[0]}")/.."

# gen_secret prints 64 hex characters (32 random bytes) using openssl or node.
gen_secret() {
  if command -v openssl >/dev/null 2>&1; then openssl rand -hex 32
  else node -e "process.stdout.write(require('crypto').randomBytes(32).toString('hex'))"; fi
}

# ensure_secret KEY: keeps an existing .env value, otherwise generates one.
ensure_secret() {
  local key="$1" current
  current=$(_existing "$key" || true)
  if [[ -n "$current" && "$current" != "change-me"* ]]; then
    note "$key already set in $ENV_FILE — keeping it"
    printf -v "$key" '%s' "$current"
  else
    printf -v "$key" '%s' "$(gen_secret)"
    write_env "$key" "${!key}"
  fi
}

TOTAL_STAGES=10

banner "Virginia setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub: an account"
say "The code has to live in a GitHub repository so Railway can deploy it."
if confirm "Do you already have a GitHub account you want to use?"; then
  note "Great — make sure you are signed in to it in your browser."
else
  open_url "https://github.com/signup"
  step "Sign up with bstone@teamksi.com (or a personal address), verify the email, and finish the prompts."
  step "Choose the Free plan; you will only use a private repository."
fi
pause "Signed in to GitHub? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: create the private repo and push the code"
for tool in git node npm; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed or not on PATH — install it and re-run"; exit 1; }
done
open_url "https://github.com/new"
step "Repository name: virginia   ·   Visibility: Private"
step "Leave 'Add a README', .gitignore and license UNCHECKED (the project already has them)."
step "Click 'Create repository', then copy the HTTPS URL shown (ends in /virginia.git)."
ask GITHUB_REPO_URL "Paste the repository HTTPS URL:"
write_env GITHUB_REPO_URL "$GITHUB_REPO_URL"
say ""
say "Now pushing this folder to that repository. A Git Credential Manager window will"
say "open in your browser the first time — sign in to GitHub there and approve."
if confirm "Push the code to $GITHUB_REPO_URL now?"; then
  git rev-parse --verify HEAD >/dev/null 2>&1 || { git add -A && git commit -q -m "Initial commit"; }
  git branch -M main
  if git remote get-url origin >/dev/null 2>&1; then git remote set-url origin "$GITHUB_REPO_URL"; else git remote add origin "$GITHUB_REPO_URL"; fi
  if git push -u origin main; then
    printf '  %s✓ pushed%s main → origin\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("git push -u origin main (re-run after signing in to GitHub)")
    warn "push failed — usually the sign-in window was closed. Re-run this wizard to try again."
  fi
else
  SKIPPED+=("git push -u origin main")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "App secrets: password, session key, connector token"
say "Three values protect the app. They are saved to .env (git ignores it) for local use,"
say "and you will paste the same values into Railway in a later stage."
step "Pick a passphrase you can type on your phone once (it stays signed in for 90 days)."
ask_secret APP_PASSWORD "App passphrase:"
[[ -n "$APP_PASSWORD" && "$APP_PASSWORD" != "change-me" ]] || { warn "passphrase cannot be empty"; exit 1; }
write_env APP_PASSWORD "$APP_PASSWORD"
ensure_secret SESSION_SECRET
ensure_secret MCP_TOKEN
write_env DATA_DIR "./data"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Anthropic: API key with a spend limit"
say "Captures (transcripts, photos of notes) are read by Claude through the API — this is"
say "separate from your Claude.ai subscription and is billed per use (a few dollars a month at your volume)."
open_url "https://console.anthropic.com/settings/keys"
step "Sign in / create the Console account with bstone@teamksi.com and add a payment method when asked."
step "Click 'Create Key', name it 'virginia', copy the key (it is shown only once)."
ask_secret ANTHROPIC_API_KEY "Paste the API key (starts with sk-ant-):"
[[ "$ANTHROPIC_API_KEY" == sk-ant-* ]] || warn "that does not look like an Anthropic key, but continuing"
write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
write_env ANTHROPIC_MODEL "claude-opus-5-5"
open_url "https://console.anthropic.com/settings/limits"
step "On the Limits (or Billing → Spend limits) page, set a monthly limit — 25 USD is plenty to start."
note "If the page layout differs, look under Settings → Billing for 'spend limit'."
pause "Spend limit set? Press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Railway: account and project from the GitHub repo"
open_url "https://railway.com/new"
step "Sign in with GitHub (use 'Login with GitHub' so Railway can see your repositories)."
step "Choose 'Deploy from GitHub repo' → pick the 'virginia' repository → 'Deploy Now'."
step "If asked to install the Railway GitHub app, allow it for the virginia repository."
note "The first build will fail its health check until the variables in stage 7 exist — that is expected."
pause "Project created and first deploy started? Press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Railway: add the /data volume"
say "The database and uploaded photos live on a persistent volume. Without it every deploy wipes your data."
step "Open the service card → Settings → scroll to 'Volumes' → 'Add Volume' (or right-click the canvas → 'Volume' and attach it to the service)."
step "Mount path:  /data"
pause "Volume attached with mount path /data? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Railway: environment variables"
say "Open the service → 'Variables' tab → 'Raw Editor'. Paste the block below, then 'Update Variables'."
say ""
if confirm "Show the values on screen now (they include your secrets)?"; then
  printf '\n%s' "$DIM"
  printf '  APP_PASSWORD=%s\n'      "$(_existing APP_PASSWORD || true)"
  printf '  SESSION_SECRET=%s\n'    "$(_existing SESSION_SECRET || true)"
  printf '  MCP_TOKEN=%s\n'         "$(_existing MCP_TOKEN || true)"
  printf '  ANTHROPIC_API_KEY=%s\n' "$(_existing ANTHROPIC_API_KEY || true)"
  printf '  ANTHROPIC_MODEL=%s\n'   "$(_existing ANTHROPIC_MODEL || echo claude-opus-5-5)"
  printf '  DATA_DIR=/data\n'
  printf '  NODE_ENV=production\n'
  printf '%s\n' "$RESET"
else
  note "The same values are in .env in this folder — copy them from there (use DATA_DIR=/data and NODE_ENV=production on Railway)."
fi
step "After saving, Railway redeploys automatically. Wait for the deploy to turn green."
pause "Variables saved and deploy green? Press Enter."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Railway: public address + health check"
step "Service → Settings → Networking → 'Generate Domain' (port 3000 if it asks)."
step "Copy the https://…up.railway.app address."
ask APP_URL "Paste the app address (https://...):"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"
say "Checking $APP_URL/api/health ..."
if command -v curl >/dev/null 2>&1 && curl -fsS --max-time 20 "$APP_URL/api/health" >/dev/null 2>&1; then
  printf '  %s✓ the app is up%s\n' "$GREEN" "$RESET"
else
  warn "no healthy answer yet — give the deploy a minute, then open $APP_URL/api/health in the browser."
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Claude: connect the Virginia project to the tracker"
say "This lets the 'Virginia - Executive Assistant' project read and write the same tracker."
MCP_TOKEN_VALUE=$(_existing MCP_TOKEN || true)
open_url "https://claude.ai/settings/connectors"
step "Click 'Add custom connector'.  Name: Virginia tracker"
if confirm "Show the connector URL on screen (it contains the secret token)?"; then
  printf '\n  %s%s/mcp/%s%s\n\n' "$BOLD" "$APP_URL" "$MCP_TOKEN_VALUE" "$RESET"
else
  note "URL = APP_URL + /mcp/ + MCP_TOKEN (both are in .env)."
fi
step "Paste it as the URL, leave OAuth fields empty, click 'Add'."
step "Open the Virginia project → the connector toggle (paper-clip / tools menu) → enable 'Virginia tracker'."
step "Test in the project: 'Virginia, show me today's list' — Claude should call get_today."
warn "Treat that URL like a password. To rotate it: change MCP_TOKEN in Railway and update the connector."
pause "Connector added and enabled? Press Enter."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Phone install and first import"
open_url "$APP_URL"
step "Log in with your passphrase. On iPhone: Share → 'Add to Home Screen' → Virginia."
step "Settings → Import → drop 'Brandon Runnign Brain Dump.xlsm' → review the preview → Commit."
step "Settings → People: fix any direct report's brand, add Brooke Dando / Cabinets Express if you want them."
note "Daily flow: record a voice memo → tap its transcript → copy → open Virginia → Capture → paste → Review → accept."
pause "All set? Press Enter to finish."

finish
